import{_ as e,H as s,f as p,i as n}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"09 | 为什么ECB模式不安全？","description":"","frontmatter":{},"headers":[{"level":2,"title":"链接模式怎么连？","slug":"链接模式怎么连","link":"#链接模式怎么连","children":[]},{"level":2,"title":"ECB模式什么样？","slug":"ecb模式什么样","link":"#ecb模式什么样","children":[]},{"level":2,"title":"缺失带来了什么问题？","slug":"缺失带来了什么问题","link":"#缺失带来了什么问题","children":[]},{"level":2,"title":"什么时候使用ECB模式？","slug":"什么时候使用ecb模式","link":"#什么时候使用ecb模式","children":[]},{"level":2,"title":"Take Away（今日收获）","slug":"take-away-今日收获","link":"#take-away-今日收获","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"实用密码学/09-为什么ECB模式不安全？.md","filePath":"实用密码学/09-为什么ECB模式不安全？.md","lastUpdated":1779819767000}'),t={name:"实用密码学/09-为什么ECB模式不安全？.md"};function i(l,a,c,o,d,h){return s(),p("div",null,[...a[0]||(a[0]=[n(`<h1 id="_09-为什么ecb模式不安全" tabindex="-1">09 | 为什么ECB模式不安全？ <a class="header-anchor" href="#_09-为什么ecb模式不安全" aria-label="Permalink to &quot;09 | 为什么ECB模式不安全？&quot;">​</a></h1><p>你好，我是范学雷。</p><p>上一讲，我们讨论了对称密钥分组算法的计算过程，我们找到了影响对称密钥算法安全性的五个关键因素，以及初始化向量对算法安全性的影响和选择。</p><p>不过，还有一些遗留的问题，我们没有来得及讨论，链接模式和数据补齐方案对算法安全性有什么样的影响？它们是怎么影响分组算法安全性的呢？我们又该怎么避免这些安全陷阱呢？</p><p>其实，这都是对称密钥分析的核心问题。因为，可以说，每一种链接模式、每一种数据补齐方案都有着不同的构造，当然也就对应着不同的分析办法，而且分析起来都较为复杂。</p><p>这一讲，我们先来分析链接模式对安全性的影响，同时，我们还可以借此机会研究一下ECB模式到底有什么问题。还记得吧？我们在开篇词提到过，它不是一个安全的加密模式。</p><p>在讲ECB模式之前，首先，我们先来看看链接模式是怎么一回事。</p><h2 id="链接模式怎么连" tabindex="-1">链接模式怎么连？ <a class="header-anchor" href="#链接模式怎么连" aria-label="Permalink to &quot;链接模式怎么连？&quot;">​</a></h2><p>我们上一讲说过，链接模式指的是如何把上一个分组运算和下一个分组运算联系起来，使得上一个分组运算可以影响下一个运算。但是，这个联系是怎么建立起来的，上一个运算到底又是怎么影响下一个运算的，这个描述是模糊的。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%AE%9E%E7%94%A8%E5%AF%86%E7%A0%81%E5%AD%A6/images/320611/25b0e86ec7352c98f332f2413c6e0220.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%AE%9E%E7%94%A8%E5%AF%86%E7%A0%81%E5%AD%A6/images/320611/25b0e86ec7352c98f332f2413c6e0220.jpg" alt=""></a></p><p>从道理上来说，上一个分组运算的所有要素，都有可能参与到下一个分组运算里；下一个分组运算的每一个要素，都有可能接收上一个运算的一个要素或者几个要素的组合。</p><p>而在这之间，就会形成不同的分配组合，也就形成了不同的链接模式。</p><p>当然，你要知道，不是所有的组合都是安全的。其中，有些模式有严格的适用范围。超越了这个范围，这个算法就不再安全了。</p><p>我们需要特别关注这些限制，把每个模式的原理理解清楚，使用时不要掉进安全陷阱里。</p><h2 id="ecb模式什么样" tabindex="-1">ECB模式什么样？ <a class="header-anchor" href="#ecb模式什么样" aria-label="Permalink to &quot;ECB模式什么样？&quot;">​</a></h2><p>我们先来简单地了解一下ECB模式是怎么工作的。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%AE%9E%E7%94%A8%E5%AF%86%E7%A0%81%E5%AD%A6/images/320611/dfc31523655e5a4c72ccdc041a3d4327.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%AE%9E%E7%94%A8%E5%AF%86%E7%A0%81%E5%AD%A6/images/320611/dfc31523655e5a4c72ccdc041a3d4327.jpg" alt=""></a></p><p>上一次，我们讨论了影响对称密钥算法安全性的五个关键因素。 <strong>但是，ECB模式有所不同，它不使用链接模式，因此它也用不着初始化向量</strong>。</p><p>不使用链接模式，就意味着上一个分组运算不影响下一个分组运算，每一个数据分组的运算都是独立的。不需要初始化向量、每一个数据分组运算都是独立的，这特性令人振奋。</p><p>不需要初始化向量，还意味着ECB模式没有初始化向量管理的烦恼，有着更简单的代码。很多密码算法的接口设计和实现，为了方便使用，会使用缺省的数据。</p><p>比如说，下面的Java代码，使用的就是缺省的ECB模式。这段代码，看起来还算清爽简单：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Cipher cipher = Cipher.getInstance(&quot;AES&quot;);</span></span>
<span class="line"><span>cipher.init(Cipher.DECRYPT_MODE, secretKey);</span></span></code></pre></div><p>但是，你看，下面的代码，看起来就繁琐的多。因为我们要在加密端和解密端同步初始化向量，而且它实际上的实现要更繁琐：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>IvParameterSpec ivParameters = new IvParameterSpec(ivBytes);</span></span>
<span class="line"><span>Cipher cipher = Cipher.getInstance(&quot;AES/CBC/PKCS5Padding&quot;);</span></span>
<span class="line"><span>cipher.init(Cipher.DECRYPT_MODE, secretKey, ivParameters);</span></span></code></pre></div><p>每一个分组运算都是独立的，这更是一个充满诱惑的特性。因为，能够独立运算，也就意味着可以并行地运算，也不必按照次序运算。</p><p>可以并行运算，意味着运算效率的大幅度提高；没有次序要求，意味着每一段加密数据都可以独立地存取、解密、修改、删除。而且，添加、插入新的数据段，也不会对其他数据段产生影响。</p><p>所有的这些，都意味着良好的运算效率。这是每一个大型数据计算场景渴望的特性，比如说数据库、流媒体、视屏会议。遗憾的是，ECB模式有致命的安全缺陷。</p><p>它的致命的安全缺陷却恰好来源于它令人振奋的特性：初始化向量的缺失和链接模式的缺失。这意味着，如果我们不能拒绝它的这些诱惑，去寻找使用替代的方案，我们就会掉进这些致命的安全陷阱。</p><h2 id="缺失带来了什么问题" tabindex="-1">缺失带来了什么问题？ <a class="header-anchor" href="#缺失带来了什么问题" aria-label="Permalink to &quot;缺失带来了什么问题？&quot;">​</a></h2><p>你可能还不知道初始化向量和链接模式的缺失会带来什么问题，让我们来一起分析下。</p><p>还记得初始化向量的特点吗？如果一个加密运算缺失初始化向量，相同的明文分组就会被加密成相同的密文分组。让我们一起来看一个例子，假设有如下一段数据：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ABCDEFGHHIJKLMNO0123456789012345</span></span></code></pre></div><p>当我们使用AES-128/ECB算法加密时，我们需要把这段数据分组成两个明文分组：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ABCDEFGHHIJKLMNO</span></span>
<span class="line"><span>0123456789012345</span></span></code></pre></div><p>然后，我们加密这段数据，得到的密文（密钥“1234567890123456”）是（十六进制表示）:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1389AE9853633EBF3D35F28987FCD1187B4BFC89DD1700154482BC7EB686BB0E</span></span></code></pre></div><p>我们可以把密文按照块大小分成两段：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1389AE9853633EBF3D35F28987FCD118</span></span>
<span class="line"><span>7B4BFC89DD1700154482BC7EB686BB0E</span></span></code></pre></div><p>根据ECB加密模式的特点，我们知道第一行密文对应的数据是“ABCDEFGHHIJKLMNO”，第二行密文对应的数据是“0123456789012345”。</p><p>如果我们知道数据块对应的密文，我们就可以通过寻找重复的密文，在没有密钥，也不执行解密操作的情况下，知道对应的数据块。比如下面的密文：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>7B4BFC89DD1700154482BC7EB686BB0E1389AE9853633EBF3D35F28987FCD118</span></span></code></pre></div><p>对应的数据块是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0123456789012345ABCDEFGHHIJKLMNO</span></span></code></pre></div><p>你可能会有疑问，数据都是加密的，攻击者怎么会事先知道数据块和对应的密文呢？其实，互联网世界里，已知重复的、位置确定的数据非常多，HTTP的头部数据，HTTPS数据包的头部，URL等都是重复频率很高的数据。</p><p>只要通过定位数据块，锚定对应的密文，就可以利用已知数据块和密文寻找、推断未知数据了。</p><p>而且，很多应用的场景，尤其是互联网的应用场景，注入特定明文数据、获取对应密文信息的攻击也是轻而易举的事情。如果攻击者没有“0123456789012345”的密文信息，他可以构造一个这样的明文，然后让密钥持有者加密，然后他就可以获得对应的密文分组。</p><p>攻击者也许并不满足于看看数据、窥视隐私。所以，ECB模式更严重的问题，是由链接模式的缺失带来的。链接模式的缺失，会让每一个分组运算都是独立的，密文数据当然也会是独立的。</p><p>我们一起来看下面这段数据：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>张三于二零二零年八月二十二日向李四借款人民币三十圆整，立此为证。</span></span></code></pre></div><p>假设我们加密运算时，这段数据被分割成如下的四个分组：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>张三于二零二零年</span></span>
<span class="line"><span>八月二十二日向李</span></span>
<span class="line"><span>四借款人民币三十</span></span>
<span class="line"><span>圆整，立此为证。</span></span></code></pre></div><p>还有下面这段数据：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>王二于二零二零年八月二十二日向李四借款人民币三十亿四千五百万六千圆整，立此为证。</span></span></code></pre></div><p>假设在加密运算时，这段数据也被分割成如下的五个分组：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>王二于二零二零年</span></span>
<span class="line"><span>八月二十二日向李</span></span>
<span class="line"><span>四借款人民币三十</span></span>
<span class="line"><span>亿四千五百万六千</span></span>
<span class="line"><span>圆整，立此为证。</span></span></code></pre></div><p>如果有了明文，还有了对应的密文，我们就可以重新编排密文数据，以获得想要的结果。</p><p>如果使用了ECB，我们可以把“亿四千五百万六千”这段明文分组对应的密文分组删除，那么解密的结果就是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>王二于二零二零年八月二十二日向李四借款人民币三十圆整，立此为证。</span></span></code></pre></div><p>我们也可以把“亿四千五百万六千”这段明文分组对应的密文分组插入到第一段数据的密文数据里。那么，修改的密文数据解密结果就是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>张三于二零二零年八月二十二日向李四借款人民币三十亿四千五百万六千圆整，立此为证。</span></span></code></pre></div><p>这样的结果，和原始数据相差甚远。这种攻击方式，就是常说的“分组重放”攻击。</p><h2 id="什么时候使用ecb模式" tabindex="-1">什么时候使用ECB模式？ <a class="header-anchor" href="#什么时候使用ecb模式" aria-label="Permalink to &quot;什么时候使用ECB模式？&quot;">​</a></h2><p>现在，你知道了ECB模式是一个很不安全的模式了吧，既然ECB模式这么不安全，为什么安全应用程序接口还要提供ECB模式的编程接口呢？这主要是因为，ECB模式是分组算法的基础。</p><p>分组算法的最基本运算，就是转换一个固定长度的数据块。这个单个数据块的转换，就是ECB模式下的运算。有密码学专业知识的算法工程师，可以通过合理地使用ECB模式，来构造更复杂、更安全的算法。 <strong>不过，我们不应该在一般的应用程序使用ECB模式。</strong></p><p>ECB从诞生开始，就被认为是一个不安全的加密模式，有密码学基础知识的工程师，一般不会使用它。下一节，我们会讨论一个被广泛使用的模式，以及它现在面临的挑战。</p><h2 id="take-away-今日收获" tabindex="-1">Take Away（今日收获） <a class="header-anchor" href="#take-away-今日收获" aria-label="Permalink to &quot;Take Away（今日收获）&quot;">​</a></h2><p>今天，通过解构ECB模式，我们讨论了在分组运算里，链接模式和初始化向量在分组运算里承担的角色，以及初始化向量缺失和链接模式缺失带来的问题。</p><p>最后，我们还讨论了ECB模式的实际用途，以及一个实用性的建议：我们不应该在一般的应用程序使用ECB模式。</p><p>通过今天的讨论，我们要：</p><ul><li>了解分组算法里，初始化向量缺失可能带来的问题；</li><li>了解分组算法里，链接模式缺失可能带来的问题；</li><li>知道ECB模式不是安全的模式，应用程序不应该直接使用ECB模式。</li></ul><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>今天的思考题，可能是一个稍微需要撕扯一下的挑战题。</p><p>我们前面说过，我们不应该在一般的应用程序使用ECB模式。可是，如果需要加密的数据小于一个数据分组（也就是说，数据太短，不需要使用链接），那么，我们可以使用ECB模式吗？有什么好处？有没有风险？</p><p>欢迎在留言区留言，记录、讨论你的想法。</p><p>好的，今天就这样，我们下次再聊。</p>`,75)])])}const u=e(t,[["render",i]]);export{g as __pageData,u as default};
